classdef CustomInputLayerMultiOutput < nnet.layer.Layer & nnet.internal.cnn.layer.Traceable & nnet.layer.Formattable 
    % Layer that takes a tensor in reverse-onnx dimension ordering, outputs
    % it in reverse-onnx ordering, and also outputs its NumDims. This layer
    % is only used for dlnetwork inputs whose data format is not known but
    % whose NumDims is known. The outputs are (1) an unformatted dlarray in
    % reverse-onnx ordering, and (2) an unformatted dlarray of size
    % 1xNumDims. The output of this layer only ever feeds into other
    % autogenerated custom layers that expect reverse-onnx inputs.
    
    %   Copyright 2021-2024 The MathWorks, Inc.
    
    properties(SetAccess=protected)
        NumDims             % An Integer value representing the number of dimensions 
                            % of the input data

        InputInformation    % A string informing the user about the dimension 
                            % ordering they must pass to this layer when predicting.    
        
        IsInputForwardONNX  % A logical flag for determining if the input needs to be permuted
                            % from forward to reverse ONNX dimension order

        TensorName          % Output tensor name

        DLTTensorFormat     % The DLT tensor format string, e.g., "SSCB"
    end
    
    methods
        function this = CustomInputLayerMultiOutput(layerName, tensorName, numDims, inputInformation, dltTensorFormat, isInputForwardONNX)           
            assert(isstring(layerName) || ischar(layerName), ...
                message('nnet_cnn_onnx:onnx:LayerNameArg'));
            assert(isscalar(numDims) && isnumeric(numDims), ...
                message('nnet_cnn_onnx:onnx:CustomInputLayerBadNumDims'));
            assert(isstring(inputInformation) || ischar(inputInformation), ...
                message('nnet_cnn_onnx:onnx:CustomInputLayerBadInputInfo'));
            this.Description = getString(message('nnet_cnn_onnx:onnx:CustomInputLayerDescription'));
            this.Type = getString(message('nnet_cnn_onnx:onnx:CustomInputLayerType', dltTensorFormat));
            this.Name = layerName;
            this.InputInformation = inputInformation;           
            this.NumDims = numDims;
            this.NumOutputs = 2;
            this.TensorName = tensorName;
            this.OutputNames = {tensorName, char(tensorName + "NumDims")};      
            this.IsInputForwardONNX = isInputForwardONNX;
            if isempty(this.DLTTensorFormat)
                this.DLTTensorFormat = '';
            else
                this.DLTTensorFormat = dltTensorFormat;
            end            
        end
        
        function [Z, numDims] = predict(this, X)
            if all(X.dims == 'U') && this.IsInputForwardONNX && this.NumDims > 1
                Z = permute(X, this.NumDims:-1:1);
            else
                Z = X;
            end
            numDims = dlarray(ones(1, this.NumDims, 'single'), 'UU');
        end
    end

    methods (Static = true, Access = public, Hidden = true)       
         function name = matlabCodegenRedirect(~)
             name = 'nnet.internal.cnn.coder.onnx.CustomInputLayerMultiOutput';
         end
    end
end
